<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { categoryPage, createCategory, deleteCategory, listStalls, toggleCategoryStatus, updateCategory } from '../../api/admin'
import type { Stall } from '../../api/types'
const rows = ref<Array<Record<string, any>>>([]); const stalls = ref<Stall[]>([]); const total = ref(0); const page = ref(1); const type = ref<number | undefined>(); const name = ref(''); const loading = ref(false)
const dialog = ref(false); const editing = ref(false)
const form = reactive({ id: undefined as number | undefined, stallId: 1, type: 1, name: '', sort: 0 })
async function load() { loading.value = true; try { const data = await categoryPage({ page: page.value, pageSize: 20, type: type.value, name: name.value || undefined }); rows.value = data.records || []; total.value = data.total } catch (e) { ElMessage.error((e as Error).message) } finally { loading.value = false } }
function open(row?: Record<string, any>) { editing.value = !!row; Object.assign(form, row ? { id: row.id, stallId: row.stallId || 1, type: row.type, name: row.name, sort: row.sort } : { id: undefined, stallId: stalls.value[0]?.id || 1, type: 1, name: '', sort: 0 }); dialog.value = true }
async function save() { if (!form.name.trim() || !form.stallId) return ElMessage.warning('请填写分类名称并选择档口'); try { if (editing.value) await updateCategory({ ...form }); else await createCategory({ ...form }); ElMessage.success('分类已保存'); dialog.value = false; await load() } catch (e) { ElMessage.error((e as Error).message) } }
async function toggle(row: Record<string, any>) { try { await toggleCategoryStatus(row.id, row.status ? 0 : 1); await load() } catch (e) { ElMessage.error((e as Error).message) } }
async function remove(row: Record<string, any>) { try { await ElMessageBox.confirm(`确认删除分类“${row.name}”？`, '删除分类', { type: 'warning' }); await deleteCategory(row.id); ElMessage.success('分类已删除'); await load() } catch (e) { if (e !== 'cancel') ElMessage.error((e as Error).message) } }
onMounted(async () => { try { stalls.value = await listStalls() } catch { /* ignore */ } await load() })
</script>
<template><div class="page-card"><div class="page-header"><div><h2 class="page-title">分类管理</h2><p class="page-subtitle">按档口维护菜品分类和套餐分类。</p></div></div><div class="page-actionbar"><div class="query-area"><el-input v-model="name" placeholder="分类名称" clearable style="width:180px" @keyup.enter="page=1;load()" /><el-select v-model="type" placeholder="全部类型" clearable style="width:140px" @change="page=1;load()"><el-option label="菜品分类" :value="1" /><el-option label="套餐分类" :value="2" /></el-select><el-button @click="page=1;load()">查询</el-button><span class="muted">共 {{ total }} 个分类</span></div><div class="action-area"><el-button type="primary" @click="open()">新增分类</el-button></div></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="id" label="ID" width="70" /><el-table-column prop="name" label="分类名称" min-width="160" /><el-table-column label="所属档口" min-width="150"><template #default="{ row }">{{ stalls.find(s => s.id === row.stallId)?.name || '—' }}</template></el-table-column><el-table-column label="类型" width="100"><template #default="{ row }">{{ row.type === 2 ? '套餐分类' : '菜品分类' }}</template></el-table-column><el-table-column prop="sort" label="排序" width="80" /><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'info'">{{ row.status ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" align="center" header-align="center" class-name="action-column" width="230"><template #default="{ row }"><div class="row-actions"><el-button text type="primary" @click="open(row)">编辑</el-button><el-button text @click="toggle(row)">{{ row.status ? '停用' : '启用' }}</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="load" /><el-dialog v-model="dialog" :title="editing ? '编辑分类' : '新增分类'" width="480px"><el-form label-position="top"><el-form-item label="所属档口"><el-select v-model="form.stallId" style="width:100%"><el-option v-for="s in stalls" :key="s.id" :label="s.name" :value="s.id" /></el-select></el-form-item><el-form-item label="分类类型"><el-radio-group v-model="form.type"><el-radio :value="1">菜品分类</el-radio><el-radio :value="2">套餐分类</el-radio></el-radio-group></el-form-item><el-form-item label="分类名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>

<style scoped>.row-actions{display:flex;align-items:center;gap:4px;white-space:nowrap}.row-actions .el-button{margin-left:0}</style>
